import{_ as i,o as a,c as e,aO as n}from"./chunks/framework.vjUPZZJn.js";const k=JSON.parse('{"title":"clashctl mixin 覆写规则：让指定域名绕过代理直连","description":"","frontmatter":{"date":"2026-11-23T10:30:00.000Z","title":"clashctl mixin 覆写规则：让指定域名绕过代理直连","source":[["1-知识/工具/网络代理与远程/clashctl mixin 添加域名直连规则"]],"tags":["工具","教程手册","网络代理","Linux"],"categories":["工具"],"permalink":"/pages/4c54fe"},"headers":[],"relativePath":"工具/clashctl mixin 覆写规则：让指定域名绕过代理直连.md","filePath":"工具/clashctl mixin 覆写规则：让指定域名绕过代理直连.md","lastUpdated":1795412618000}'),t={name:"工具/clashctl mixin 覆写规则：让指定域名绕过代理直连.md"};function l(p,s,h,r,d,o){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="clashctl-mixin-覆写规则-让指定域名绕过代理直连" tabindex="-1">clashctl mixin 覆写规则：让指定域名绕过代理直连 <a class="header-anchor" href="#clashctl-mixin-覆写规则-让指定域名绕过代理直连" aria-label="Permalink to &quot;clashctl mixin 覆写规则：让指定域名绕过代理直连&quot;">​</a></h1> <p>在 Linux 服务器上以订阅方式使用 Clash/mihomo 时，经常遇到一类问题：某个域名本应直连（内网服务、特定工具的 API 端点），却被订阅规则送进了代理节点，导致访问变慢甚至不通。直接改订阅生成的配置文件当然可以，但下次订阅更新就会被整个覆盖。本文记录 <a href="https://github.com/nelvko/clash-for-linux-install" target="_blank" rel="noreferrer">clash-for-linux-install</a>（提供 <code>clashctl</code> 命令的安装管理脚本）的 mixin 覆写机制：把指定域名的 DIRECT 规则持久地插到订阅规则前面，订阅更新后依然生效。适合在无桌面环境、用该脚本托管 mihomo 的读者。</p> <h2 id="clashctl-的配置布局" tabindex="-1">clashctl 的配置布局 <a class="header-anchor" href="#clashctl-的配置布局" aria-label="Permalink to &quot;clashctl 的配置布局&quot;">​</a></h2> <p>先搞清楚文件在哪、谁是谁。<code>clashctl</code> 不是独立二进制，而是 bashrc 里 source 的 shell 函数：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CLASHCTL_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/home/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/clashctl</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $CLASHCTL_HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/scripts/cmd/clashctl.sh</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>所以非交互 SSH（<code>ssh host &#39;clashctl status&#39;</code>）会报 <code>command not found</code>，需要先手动 export + source 再调用。</p> <p>配置都在 <code>$CLASHCTL_HOME/resources/</code> 下，mihomo 进程实际以 <code>-d resources -f runtime.yaml</code> 运行：</p> <table tabindex="0"><thead><tr><th>文件</th> <th>作用</th></tr></thead> <tbody><tr><td><code>config.yaml</code></td> <td>订阅原始配置，<code>clashctl sub</code> 更新时整个被覆盖</td></tr> <tr><td><code>mixin.yaml</code></td> <td>用户覆写配置，订阅更新后仍保留</td></tr> <tr><td><code>runtime.yaml</code></td> <td>mixin 与 config 合并后的最终运行配置</td></tr></tbody></table> <h2 id="为什么改-mixin-而不是直接改-config-yaml" tabindex="-1">为什么改 mixin 而不是直接改 config.yaml <a class="header-anchor" href="#为什么改-mixin-而不是直接改-config-yaml" aria-label="Permalink to &quot;为什么改 mixin 而不是直接改 config.yaml&quot;">​</a></h2> <p>Clash/mihomo 的 <code>rules</code> 是顺序匹配：想让指定域名绕过代理，必须把 DIRECT 规则插到订阅规则<strong>前面</strong>。直接编辑 <code>config.yaml</code> 虽然立刻生效，但下次订阅更新就被冲掉。<code>mixin.yaml</code> 是该项目官方的持久化覆写机制，合并逻辑在 <code>scripts/lib/config.sh</code> 里：</p> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>runtime.rules = mixin.rules.prepend + config.rules + mixin.rules.append</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>mixin 各字段的适用范围（<code>mixin.yaml</code> 文件头部注释有说明）：</p> <table tabindex="0"><thead><tr><th>字段</th> <th>行为</th> <th>适用</th></tr></thead> <tbody><tr><td><code>prepend</code></td> <td>插到原列表开头</td> <td><code>rules</code>、<code>proxies</code>、<code>proxy-groups</code></td></tr> <tr><td><code>append</code></td> <td>追加到原列表末尾</td> <td><code>rules</code>、<code>proxies</code>、<code>proxy-groups</code></td></tr> <tr><td><code>override</code></td> <td>按 name 整体替换</td> <td><code>proxies</code>、<code>proxy-groups</code></td></tr> <tr><td><code>inject</code></td> <td>向指定 proxy-group 注入节点</td> <td><code>proxy-groups</code></td></tr></tbody></table> <p>一个容易踩的坑：项目 wiki 上写的字段是顶层 <code>prepend-rules</code>，但实际安装版本用的是嵌套结构 <code>rules.prepend</code>。字段写法以安装版本的合并脚本（<code>scripts/lib/config.sh</code>）为准，别照抄 wiki。</p> <h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2> <p>编辑 <code>resources/mixin.yaml</code>，在 <code>rules.prepend</code> 列表加一条（改前先备份）。示例让 <code>zcode.z.ai</code> 及其子域直连：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $CLASHCTL_HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/resources</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mixin.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mixin.yaml.bak</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在 rules: -&gt; prepend: 下追加一条，或用 sed 插到现有条目后</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/api64.ipify.org/a\\    - DOMAIN-SUFFIX,zcode.z.ai,DIRECT&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mixin.yaml</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>合并后的 <code>rules</code> 段长这样：</p> <div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  prepend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DOMAIN,api64.ipify.org,DIRECT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DOMAIN-SUFFIX,zcode.z.ai,DIRECT</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 新增</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  append</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>生效走项目自己的合并重启路径，<code>clashctl mixin -e</code> 保存后自动触发；非交互场景直接调内部函数（效果等价）：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CLASHCTL_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/home/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/clashctl</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $CLASHCTL_HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/scripts/cmd/clashctl.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">_merge_config_restart</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 合并校验，失败会回滚 runtime.yaml，成功则重启 mihomo</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>注意 <code>_merge_config_restart</code> 会重启 mihomo 进程，已建立的长连接（如流式 API 的 SSE 连接）会被掐断，客户端重连即走新规则。</p> <h2 id="验证-三步缺一不可" tabindex="-1">验证：三步缺一不可 <a class="header-anchor" href="#验证-三步缺一不可" aria-label="Permalink to &quot;验证：三步缺一不可&quot;">​</a></h2> <p><strong>1. 确认规则进了运行时配置且排在订阅规则前。</strong> 通过 mihomo 的外部控制 API 查规则顺序（secret 在 mixin.yaml / runtime.yaml 里）：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;secret&gt;&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:9090/rules</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import json,sys; [print(r[&#39;type&#39;], r[&#39;payload&#39;], &#39;-&gt;&#39;, r[&#39;proxy&#39;]) for r in json.load(sys.stdin)[&#39;rules&#39;][:3]]&quot;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>输出前几条应包含 <code>DomainSuffix zcode.z.ai -&gt; DIRECT</code>。</p> <p><strong>2. 实际打一发流量，看日志命中。</strong> 查 rules 只能证明配置加载了，命中要看过连接日志：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:7890</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://zcode.z.ai</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;zcode.z.ai&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $CLASHCTL_HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/resources/mihomo.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -2</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>日志出现 <code>match DomainSuffix(zcode.z.ai) using DIRECT</code> 才算真生效。</p> <p><strong>3. 确认本机直连本来就能通。</strong> 如果目标域名直连本身不可达，改成 DIRECT 反而把服务弄断了：</p> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --noproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;*&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;%{http_code} %{time_total}s\\n&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://zcode.z.ai</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2> <p>改代理规则优先找“覆写/override/mixin”这类机制，不直接动订阅生成的配置文件，否则更新即丢；字段写法以安装版本的合并脚本为准，wiki 文档可能落后于实际版本；生效验证不能只看配置加载，要打过真实流量看连接日志，并事先确认直连链路本身可达。规则粒度按需选：<code>DOMAIN-SUFFIX,zcode.z.ai</code> 只管该域及其子域，后续发现同主域其他子域也要直连时，可放宽为 <code>DOMAIN-SUFFIX,z.ai</code>。</p> <h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2> <ul><li><a href="https://github.com/nelvko/clash-for-linux-install" target="_blank" rel="noreferrer">nelvko/clash-for-linux-install</a>（<code>clashctl</code> 与 mixin 合并逻辑的实现仓库）</li> <li><a href="https://github.com/MetaCubeX/mihomo" target="_blank" rel="noreferrer">MetaCubeX/mihomo</a>（规则顺序匹配与外部控制 API 所属内核）</li></ul>`,61)])])}const g=i(t,[["render",l]]);export{k as __pageData,g as default};
